import{rt as e,t,tt as n,xt as r}from"./chunks/framework.CRPOboOd.js";var i=JSON.parse(`{"title":"Auth and Gateway","description":"","frontmatter":{"title":"Auth and Gateway","order":3},"headers":[],"relativePath":"architecture/auth-and-gateway.md","filePath":"architecture/auth-and-gateway.md"}`),a={name:`architecture/auth-and-gateway.md`};function o(t,i,a,o,s,c){return r(),n(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1793506373000`},[...i[0]||=[e(`<h1 id="auth-and-gateway" tabindex="-1">Auth and Gateway <a class="header-anchor" href="#auth-and-gateway" aria-label="Permalink to “Auth and Gateway”">​</a></h1><h2 id="public-traffic" tabindex="-1">Public traffic <a class="header-anchor" href="#public-traffic" aria-label="Permalink to “Public traffic”">​</a></h2><p>All public traffic enters through Traefik, routed by path prefix on a single API host (<code>/note</code>, <code>/authorization</code>, <code>/document</code>, <code>/billing</code>, ...). Traefik validates the Authentik JWT with a JWT middleware, maps the OIDC <code>roles</code> claim, and injects user headers downstream. Each service excludes its own health path from the middleware, and endpoints that must skip auth (such as the Stripe webhook) have their own router.</p><ul><li>Go services read the user with <code>commonhttp.GatewayUserAuth()</code>.</li><li>NestJS services use <code>UserGuard</code> and the <code>@User()</code> decorator.</li><li>Exception: the <code>apps/document</code> websocket (<code>/document/ws/document</code>) validates the JWT itself.</li></ul><h2 id="internal-traffic" tabindex="-1">Internal traffic <a class="header-anchor" href="#internal-traffic" aria-label="Permalink to “Internal traffic”">​</a></h2><p>Service-to-service calls use gRPC (definitions in <code>proto/</code>, see <a href="./../api/grpc/">gRPC reference</a>). A service never calls another service&#39;s public REST API internally. For example, Note and Billing call the Authorization service over gRPC for permission checks, and Note calls Billing for entitlements on every check without caching.</p>`,6)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};